package com.worksphere.service; import com.worksphere.dto.profile.*; import com.worksphere.entity.*; import com.worksphere.repository.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; @Service public class EmployerProfileService {private final EmployerProfileRepository repo;private final UserService users;public EmployerProfileService(EmployerProfileRepository r,UserService u){repo=r;users=u;} private EmployerProfile p(Authentication a){return repo.findByUserId(users.current(a).id).orElseThrow();} public EmployerProfileResponse get(Authentication a){EmployerProfile p=p(a);return new EmployerProfileResponse(p.id,p.user.id,p.user.fullName,p.companyName,p.location,p.bio,p.rating,p.ratingCount);} public EmployerProfileResponse save(Authentication a,EmployerProfileRequest r){EmployerProfile p=p(a);p.companyName=r.companyName();p.location=r.location();p.bio=r.bio();repo.save(p);return get(a);} }
